const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// CSV is a human spreadsheet view. Exact unmodified text also travels in JSONL.
const csv = value => '"' + String(value ?? '').replace(/^[=+@\-]/, "'$&").replaceAll('"','""') + '"';
const decode = row => {
  const data={...row, ...Object.fromEntries(['baseline','returned','current','desired','blockers'].map(k=>[k,JSON.parse(row[k])]))};
  const details=JSON.parse(row.details||'{}');
  if(row.kind==='measurement')for(const role of ['baseline','returned','current','desired']){
    data[role].records=data[role].records.map(record=>({...record,display:details[role==='desired'?'current':role]?.[record.id]||{}}));
  }
  delete data.details;return data;
};

