function render(){const visible=selectedRows();offset=Math.min(offset,Math.max(0,Math.floor((visible.length-1)/pageSize)*pageSize));$('changes').innerHTML=visible.slice(offset,offset+pageSize).map(r=>{const i=rowIndex.get(r),choice=choices.get(token(r));return '<article class="change"><div class="change-head"><div><span class="pill">'+e(r.classification.replaceAll('-',' '))+'</span><h3>'+e(r.kind==='measurement'?(r.returned.records[0]?.display?.characteristic||r.returned.records[0]?.parameter||'Measurement group')+' · '+(r.returned.records[0]?.sampledDate||''):r.key)+'</h3><code>'+e(r.key)+'</code></div><label>Incorporation choice<select data-choice="'+i+'"><option value="" '+(!choice?'selected':'')+'>Choose explicitly</option><option value="current" '+(choice==='current'?'selected':'')+'>Keep current</option><option value="return" '+(choice==='return'?'selected':'')+' '+(r.classification==='source-needed'?'disabled':'')+'>Use returned changes</option></select></label></div>'+(r.blockers.length?'<div class="notice">'+r.blockers.map(e).join('<br>')+'</div>':'')+'<div class="branches">'+[['baseline','Sent baseline'],['returned','Returned reviewer'],['current','Current scientist']].map(([k,title])=>'<section class="branch"><h3>'+title+'</h3>'+branchHTML(r[k],r.kind)+'</section>').join('')+'</div><details><summary>Proposed result when using returned changes</summary>'+branchHTML(r.desired,r.kind)+'</details></article>';}).join('')||'<p>No changes match this view. The original current work is retained.</p>';$('page').textContent=visible.length?(offset+1)+'–'+Math.min(offset+pageSize,visible.length)+' of '+visible.length+' changed groups':'No changed groups';$('previous').disabled=offset===0;$('next').disabled=offset+pageSize>=visible.length;}
