}

/** Whole-collection UI inside the existing measured-data authenticated transport. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sha=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
const base64=buffer=>{const a=new Uint8Array(buffer);let s='';for(let i=0;i<a.length;i+=8192)s+=String.fromCharCode(...a.subarray(i,i+8192));return btoa(s);};
export function mountCollectionPanel(host,{request,refresh}){
  const lifecycle=new AbortController();let files=[],inspected=null,busy=false,dead=false,version=0;
  host.classList.add('measured-collections');
  host.style.cssText='margin:18px;padding:18px;border:1px solid #ccc;background:#fafafa;font:14px system-ui;color:#222';
  host.innerHTML=`<details><summary><strong>Receive a complete observation collection</strong></summary><p>Keep chemistry, stations and accompanying original files together. Choose each file's interpretation; companion files remain byte-exact originals.</p><form><label>Collection title <input name="title" required style="width:100%"></label><p><input name="sources" aria-label="Collection source files" type="file" multiple required></p><div data-files style="overflow:auto"></div><p><button data-preview type="submit">Inspect all files</button> <button data-receive type="button" disabled>Receive complete collection</button></p></form><p role="status" aria-live="polite"></p><div data-inspection-summary style="overflow:auto"></div><details><summary>Column mappings and import diagnostics</summary><pre data-preview-result style="white-space:pre-wrap;max-height:22em;overflow:auto"></pre></details></details><details><summary>Saved collections and complete study editions</summary><button data-refresh type="button">Refresh collections</button><div data-list></div></details>`;
  const status=host.querySelector('[role=status]'),form=host.querySelector('form');
  const message=text=>{if(!dead)status.textContent=text;};
  async function api(path,method='GET',payload){const response=await request(path,method,payload);const text=await response.text();if(!response.ok)throw new Error(text);return JSON.parse(text);}
  async function run(fn){if(busy)return;busy=true;host.setAttribute('aria-busy','true');try{await fn();}catch(error){message(error.message);}finally{busy=false;host.setAttribute('aria-busy','false');}}
  function invalidate(){version++;inspected=null;host.querySelector('[data-receive]').disabled=true;}
  form.addEventListener('input',invalidate,{signal:lifecycle.signal});
  form.elements.sources.addEventListener('change',()=>{
    files=Array.from(form.elements.sources.files);invalidate();
    host.querySelector('[data-files]').innerHTML='<table style="border-collapse:collapse;width:100%"><thead><tr><th>Original file</th><th>Interpretation</th><th>Optional column mapping JSON</th></tr></thead><tbody>'+files.map((f,i)=>`<tr><td>${esc(f.name)} (${f.size} bytes)</td><td><select name="kind-${i}" aria-label="Interpretation ${esc(f.name)}"><option value="companion">Retained companion</option><option value="wqp">Chemistry / WQP</option><option value="stations">Monitoring stations</option><option value="usgs-daily">Daily discharge</option></select></td><td><input name="mapping-${i}" aria-label="Mapping ${esc(f.name)}" value="{}"></td></tr>`).join('')+'</tbody></table>';
  },{signal:lifecycle.signal});
  async function input(){return {format:'upper-savannah-measurement-collection/v1',title:form.elements.title.value,files:await Promise.all(files.map(async(file,i)=>{const data=await file.arrayBuffer();return {path:file.name,label:file.name,kind:form.elements['kind-'+i].value,mapping:JSON.parse(form.elements['mapping-'+i].value),sha256:await sha(data),base64:base64(data)};}))};}
  form.addEventListener('submit',event=>{event.preventDefault();run(async()=>{const selectedVersion=version;message('Inspecting every complete source…');const document=await input();const preview=await api('/collections/preview','POST',document);if(dead)return;if(selectedVersion!==version){message('Files changed during inspection; inspect the current collection again.');return;}inspected={...document,expectedId:preview.id};host.querySelector('[data-inspection-summary]').innerHTML='<table style="border-collapse:collapse;width:100%"><thead><tr><th>Original file</th><th>Interpretation</th><th>Complete rows</th><th>Rejected rows</th></tr></thead><tbody>'+preview.inspection.map(f=>`<tr><td>${esc(f.path)}</td><td>${esc(f.kind)}</td><td>${f.preview?esc(f.preview.rows):'Retained original'}</td><td>${f.preview?esc(f.preview.rejectedCount):'—'}</td></tr>`).join('')+'</tbody></table>';host.querySelector('[data-preview-result]').textContent=JSON.stringify(preview.inspection.map(f=>({path:f.path,kind:f.kind,bytes:f.bytes,rows:f.preview?.rows,rejected:f.preview?.rejectedCount,issues:f.preview?.issues,mapping:f.preview?.mapping})),null,2);host.querySelector('[data-receive]').disabled=false;message('All original files inspected. Receiving will retain complete originals and use the existing measurement engine.');});},{signal:lifecycle.signal});
  async function list(){const value=await api('/collections');if(dead)return;host.querySelector('[data-list]').innerHTML=value.collections.length?value.collections.map(c=>`<article style="border-top:1px solid #ccc;padding:12px 0"><strong>${esc(c.title)}</strong><p>${c.fileCount} original files · ${c.complete?'received':'receiving interrupted; resend the same collection'}</p><button data-publish="${c.id}"${c.complete?'':' disabled'}>Save complete study edition</button><div data-editions="${c.id}">${c.editions.map(id=>`<button data-edition="${id}" data-collection="${c.id}">Edition ${id.slice(0,12)}</button>`).join(' ')}</div></article>`).join(''):'<p>No saved collections.</p>';}
  function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  async function showEdition(collection,id){
    const edition=await api(`/collections/${collection}/editions/${id}`);if(dead)return;
    const box=host.querySelector(`[data-editions="${collection}"]`);box.replaceChildren();
    const p=document.createElement('p');p.textContent=`Revision ${edition.workspaceRevision}: ${edition.recordCount} complete records; ${edition.counts.accepted} eligible inputs, ${edition.counts.excluded} exclusions.`;box.append(p);
    const b=document.createElement('button');b.type='button';b.textContent='Download complete editable study ZIP';b.addEventListener('click',()=>run(async()=>{const value=await api(`/collections/${collection}/editions/${id}/bundle`);const bytes=Uint8Array.from(atob(value.base64),c=>c.charCodeAt(0));if(bytes.length!==value.bytes||await sha(bytes)!==value.sha256)throw new Error('Study download differs from its saved edition');download(value.name,bytes,value.type);}),{signal:lifecycle.signal});box.append(b);
  }
  host.addEventListener('click',event=>{const target=event.target.closest('button');if(!target||(!target.hasAttribute('data-receive')&&!target.hasAttribute('data-refresh')&&!target.dataset.publish&&!target.dataset.edition))return;run(async()=>{
    if(target.hasAttribute('data-receive')){if(!inspected)throw new Error('Inspect the collection again after editing');message('Receiving complete originals…');const value=await api('/collections/receive','POST',inspected);message(`Collection received at workspace revision ${value.workspaceRevision}.`);await list();await refresh();}
    else if(target.hasAttribute('data-refresh'))await list();
    else if(target.dataset.publish){message('Saving a complete revision-pinned study edition…');const result=await api(`/collections/${target.dataset.publish}/publish`,'POST',{});await list();await showEdition(target.dataset.publish,result.id);message('Complete editable project, originals, reports and record exports saved.');}
    else if(target.dataset.edition)await showEdition(target.dataset.collection,target.dataset.edition);
  });},{signal:lifecycle.signal});
  list().catch(error=>message(error.message));
  return {destroy(){dead=true;lifecycle.abort();host.replaceChildren();}};
}

import {mountReturnedReviews} from './returned_reviews.mjs';
