 function controls(){if(destroyed)return;for(const button of host.querySelectorAll('button,input,select,textarea'))button.disabled=busy;q('[data-pause]').disabled=!busy;q('[data-commit]').disabled=busy||!preview||active?.kind==='portable'||active?.phase==='committed';q('[data-receive]').disabled=busy||active?.kind!=='portable'||active.offset!==active.bytes;}
