 function showPreview(value){preview=value;const s=value.summary;const sample=value.sample||[];q('[data-preview]').innerHTML=`<h3>Reviewed complete original</h3><p><strong>${s.rows.toLocaleString()} accepted source rows</strong> · ${s.rejectedCount.toLocaleString()} rejected · ${s.stationCount.toLocaleString()} stations · ${s.censored.toLocaleString()} censored results</p><p><code>${escape(value.sourceSha256)}</code></p><p><small>The first ${sample.length} normalized records are shown. The full original and every rejected row remain retained.</small></p><div class="scroll"><table><thead><tr><th>Physical line</th><th>Station</th><th>Date</th><th>Constituent</th><th>Value / bounds</th><th>Source issues</th></tr></thead><tbody>${sample.map(r=>`<tr><td>${r.sourceLine}</td><td>${escape(r.stationId||r.id)}</td><td>${escape(r.sampledDate)}</td><td>${escape(r.characteristic)}</td><td>${escape(r.value??'—')} ${escape(r.unit)}<br>${escape(r.lower??'—')} to ${escape(r.upper??'—')} (${escape(r.censor||'station')})</td><td>${escape((r.issues||[]).join(', '))}</td></tr>`).join('')}</tbody></table></div>`;}
 async function selectIntake(id){active=await call('/intakes/'+id);idField.value=id;q('[data-kind]').value=active.kind;q('[data-label]').value=active.label;q('[data-mapping]').value=JSON.stringify(active.mapping,null,2);preview=null;if(active.prepared)showPreview({...active.prepared,workspaceRevision:active.workspaceRevision});else q('[data-preview]').replaceChildren();status.textContent=`${active.phase} · ${bytes(active.offset)} of ${bytes(active.bytes)} retained. ${active.label}`;controls();}
 async function refreshLists(){if(destroyed)return;const [intakes,editions,sources]=await Promise.all([call('/intakes'),call('/editions'),call('/sources')]);if(destroyed)return;
  q('[data-intakes]').innerHTML=intakes.intakes.length?`<table><thead><tr><th>Original</th><th>Status</th><th>Received</th><th>Reopen</th></tr></thead><tbody>${intakes.intakes.map(i=>`<tr><td>${escape(i.label)}<br><code>${i.id}</code></td><td>${escape(i.phase)}</td><td>${bytes(i.offset)} / ${bytes(i.bytes)}</td><td><button data-select="${i.id}">Select</button></td></tr>`).join('')}</tbody></table>`:'<p>No retained large-file intakes.</p>';
  q('[data-editions]').innerHTML=editions.editions.length?editions.editions.map(e=>e.files?`<article><strong>Revision ${e.workspaceRevision}</strong> · ${e.recordCount.toLocaleString()} records · ${e.counts.accepted.toLocaleString()} eligible / ${e.counts.excluded.toLocaleString()} excluded<br><code>${e.id}</code><div class="actions">${e.files.map(f=>`<button data-download="${e.id}" data-member="${escape(f.path)}">${escape(f.path)} · ${bytes(f.bytes)}</button>`).join('')}</div></article>`:`<article>${escape(e.phase)} · <code>${e.id}</code><button data-resume-export="${e.id}">Resume saved edition</button></article>`).join(''):'<p>No saved complete editions.</p>';
  q('[data-sources]').innerHTML=sources.sources.length?`<table><thead><tr><th>Original source</th><th>Complete files</th></tr></thead><tbody>${sources.sources.map(source=>`<tr><td>${escape(source.label)}<br>${source.summary.rows.toLocaleString()} source rows · ${source.summary.rejectedCount.toLocaleString()} rejected</td><td><div class="actions">${[source.kind==='usgs-daily'?'original.geojson':'original.csv','rejections.jsonl','source.json'].map(name=>`<button data-original="${source.id}" data-member="${name}">${name}</button>`).join('')}</div></td></tr>`).join('')}</tbody></table>`:'<p>No original sources have been imported.</p>';
  for(const button of host.querySelectorAll('[data-original]'))button.onclick=()=>perform(token=>download(button.dataset.original,button.dataset.member,token,'sources'));
  for(const button of host.querySelectorAll('[data-select]'))button.onclick=()=>perform(()=>selectIntake(button.dataset.select));
  for(const button of host.querySelectorAll('[data-download]'))button.onclick=()=>perform(token=>download(button.dataset.download,button.dataset.member,token));
  for(const button of host.querySelectorAll('[data-resume-export]'))button.onclick=()=>perform(token=>saveEdition(token,button.dataset.resumeExport));controls();
 }
 async function upload(token){
  const file=q('[data-file]').files[0];if(!file)throw new Error('Choose the complete original file.');const kind=q('[data-kind]').value,label=q('[data-label]').value.trim()||file.name,mapping=JSON.parse(q('[data-mapping]').value||'{}');
  if(getId())active=await call('/intakes/'+getId());
  else{const id=newId();idField.value=id;active=await call('/intakes','POST',{id,kind,label,bytes:file.size,mapping,origin:{type:'file',filename:file.name}});}check(token);
  if(active.kind!==kind||active.bytes!==file.size)throw new Error('The selected source kind or file size differs from this retained intake. Clear the intake identifier to start a different original.');idField.value=active.id;
  const retained=active.offset;
  for(let offset=0;offset<file.size;offset+=CHUNK){check(token);const data=new Uint8Array(await file.slice(offset,offset+CHUNK).arrayBuffer()),sha256=await digestBytes(data);check(token);
   const prefix=offset<retained;const result=await call('/intakes/'+active.id+'/chunks','PUT',{offset,sha256,...(prefix?{check:true}:{base64:encode(data)})});check(token);if(prefix&&!result.reused)throw new Error('Retained upload prefix changed; reopen this intake.');active.offset=result.offset;progress.value=(offset+data.length)/file.size;status.textContent=`${prefix?'Checked retained prefix':'Received original'}: ${bytes(offset+data.length)} / ${bytes(file.size)}`;
  }
  if(kind==='portable'){status.textContent='Complete archive received. Use “Receive complete project” in an empty measured workspace.';return;}
  status.textContent='Preparing the complete original with the existing measurement normalizer…';const value=await call('/intakes/'+active.id+'/prepare','POST',{});check(token);active=await call('/intakes/'+active.id);showPreview(value);status.textContent=`Complete preview ready: ${value.summary.rows.toLocaleString()} source rows. Review the source interpretation, then commit.`;
 }
 async function saveEdition(token,id=newId()){status.textContent='Capturing one native revision and saving its complete outputs… Retained edition '+id;const edition=await call('/editions','POST',{id});check(token);status.textContent=`Saved revision ${edition.workspaceRevision}: ${edition.recordCount.toLocaleString()} records, ${edition.files.length} complete output files.`;await refresh();}
 async function download(id,name,token,kind='editions'){
  const edition=await call('/'+kind+'/'+id),member=edition.files.find(f=>f.path===name);if(!member)throw new Error('Saved member is unavailable.');check(token);let writable,handle,directory;const parts=[];const temporary='measurement-'+id+'-'+name;
  try{
   if(navigator.storage?.getDirectory){try{directory=await navigator.storage.getDirectory();handle=await directory.getFileHandle(temporary,{create:true});writable=await handle.createWritable();}catch{if(directory)await directory.removeEntry(temporary).catch(()=>{});directory=null;handle=null;writable=null;}}
   if(!writable)status.textContent='This browser uses memory-backed downloads; the installed CLI can write this entire edition directly to disk.';
   for(let index=0;index<member.chunks.length;index++){check(token);const chunk=await call('/'+kind+'/'+id+'/files/'+encodeURIComponent(name)+'/'+index),data=decode(chunk.base64);if(await digestBytes(data)!==member.chunks[index])throw new Error('Saved download chunk checksum differs.');check(token);if(writable)await writable.write(data);else parts.push(data);check(token);progress.value=(index+1)/member.chunks.length;status.textContent=`Receiving saved ${name}: ${bytes(Math.min((index+1)*CHUNK,member.bytes))} / ${bytes(member.bytes)}`;}
   if(writable){await writable.close();writable=null;}check(token);const blob=handle?await handle.getFile():new Blob(parts);check(token);if(blob.size!==member.bytes)throw new Error('Complete downloaded member length differs.');const url=URL.createObjectURL(blob);urls.add(url);const link=document.createElement('a');link.href=url;link.download=name;link.click();status.textContent=`Complete ${name} received (${bytes(member.bytes)}). SHA-256 ${member.sha256}`;
   if(directory)cleanup.push(()=>directory.removeEntry(temporary).catch(()=>{}));
  }catch(error){if(writable)await writable.abort().catch(()=>{});if(directory)await directory.removeEntry(temporary).catch(()=>{});throw error;}
 }
 q('[data-new]').onclick=()=>{if(busy)return;preview=null;active=null;idField.value='';q('[data-label]').value=q('[data-file]').files[0]?.name||'';q('[data-mapping]').value='{}';q('[data-preview]').replaceChildren();progress.value=0;status.textContent='New original selected. Existing saved intakes remain available below.';controls();};
 q('[data-upload]').onclick=()=>perform(upload);
 q('[data-reprocess]').onclick=()=>perform(async token=>{if(!getId())throw new Error('Select a retained original.');active=await call('/intakes/'+getId(),'PUT',{label:q('[data-label]').value,mapping:JSON.parse(q('[data-mapping]').value||'{}')});const value=await call('/intakes/'+getId()+'/prepare','POST',{});check(token);active.phase='prepared';showPreview(value);status.textContent='Complete original reprocessed without another upload.';});
 q('[data-commit]').onclick=()=>perform(async token=>{if(getId()!==preview?.id||active?.id!==preview?.id)throw new Error('Reopen and review the selected original before committing.');const value=await call('/intakes/'+preview.id+'/commit','POST',{expectedRevision:preview.workspaceRevision,expectedSourceSha256:preview.sourceSha256,expectedNormalizerPin:preview.normalizerPin});check(token);active.phase='committed';status.textContent=`Committed complete source: ${value.rows.toLocaleString()} rows at native revision ${value.revision}.`;await refresh();});
 q('[data-receive]').onclick=()=>perform(async token=>{status.textContent='Verifying complete originals and receiving the editable measurement project…';const value=await call('/intakes/'+getId()+'/receive','POST',{});check(token);status.textContent=`Received ${value.recordCount.toLocaleString()} records at revision ${value.revision}. Reviews and saved outputs are independently editable.`;await refresh();});
