 refreshLists().catch(error=>{if(!destroyed)status.textContent=error.message;});controls();
 return {refresh:refreshLists,destroy(){destroyed=true;epoch++;for(const url of urls)URL.revokeObjectURL(url);for(const fn of cleanup)fn();host.replaceChildren();}};
