  host.classList.add('mw');
  host.innerHTML=`<header class="mw-head"><div><div class="mw-eyebrow">UPPER SAVANNAH / OPERATOR WORKSPACE</div><h1>Measured data</h1><p>Receive originals. Inspect measurements. Assign native reaches. Export reviewed inputs.</p></div><button data-action="refresh">Refresh</button></header><div class="mw-stats" aria-label="Workspace totals"></div><nav class="mw-nav" aria-label="Measured data"><button data-tab="sources">Receive sources</button><button data-tab="records">Measurements</button><button data-tab="stations">Station assignments</button><button data-tab="flow">Daily flow</button><button data-tab="source-review">Source versions</button><button data-tab="exports">Exports &amp; handover</button><button data-tab="handback">Source returns</button><button data-tab="results">Saved results</button><button data-tab="archive">Source archive</button></nav><div class="mw-status" role="status" aria-live="polite">Opening saved workspace…</div><section class="mw-content"></section>`;
  const area=host.querySelector('.mw-content'),status=host.querySelector('.mw-status');
