    [r.label || r.id, r.id && 'Source ' + r.id, r.sha && 'SHA-256 ' + r.sha,
      r.source_line != null && 'Line ' + r.source_line, r.created_at && 'Imported ' + r.created_at].filter(Boolean).join(' · ')).join('\n');
  return cell(value);
