.source-handback dt{font-size:12px;color:#555;overflow-wrap:anywhere}
.source-handback dd{margin:0;font-weight:700;color:#222;overflow-wrap:anywhere}
.source-handback .sh-scroll{overflow:auto;max-width:100%;max-height:650px;border:1px solid #bbb;background:#fff;color:#222;margin:12px 0}
.source-handback table{border-collapse:collapse;width:100%;font-size:13px;background:#fff;color:#222}
