.source-handback .sh-original{white-space:pre-wrap}
.source-handback pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;color:#222;background:#f3f3ef;padding:12px;max-height:440px;overflow:auto}
